import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"6.2 Revoke devices and migrate safely","description":"A lost device can be disabled immediately, and data moves fully when replacing it.","frontmatter":{"title":"6.2 Revoke devices and migrate safely","description":"A lost device can be disabled immediately, and data moves fully when replacing it.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-6/6-2.md","filePath":"en/delivery/stage-6/6-2.md","lastUpdated":1794017073000}'),r={name:"en/delivery/stage-6/6-2.md"};function s(l,e,d,n,c,v){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_6-2-revoke-devices-and-migrate-safely" tabindex="-1">6.2 Revoke devices and migrate safely <a class="header-anchor" href="#_6-2-revoke-devices-and-migrate-safely" aria-label="Permalink to &quot;6.2 Revoke devices and migrate safely&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Task leases carry TTL, owner, and epoch; after expiry another instance can take over and advance the epoch, and the old owner submissions and results are rejected; device capabilities can be revoked, tokens rotated, and devices re-paired; a global kill switch blocks approvals and scheduler restarts and records a security audit.</li><li><strong>Still open:</strong> No dedicated cross-device artifact/workspace migration flow and no real lost-device drill; lifting the global stop requires an explicit executor restart.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let a lost, replaced, or migrated device be revoked and transferred safely; after revocation, the old device cannot approve, take over, or view data.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Provide an immediate revoke entry; after revocation, all sessions and approval authority become invalid at once.</li><li>After revocation, verify the old device cannot receive tasks, view artifacts, or perform actions.</li><li>Use a safe migration flow when replacing a device, then verify tasks, artifacts, memory, and authority afterwards.</li><li>Route tasks by device capability: desktop actions go to a device with desktop ability; the phone only views, approves, and takes over.</li><li>Record the revocation and migration so the user can review them.</li><li>Run a lost-device drill from revocation to confirming the old device is disabled.</li></ol>',7)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
